import pytest

from breadth_first_search import breadth_first_search


class Node:
    def __init__(self, name):
        self.name = name
        self.successors = []

    def __repr__(self):
        return f"Node({self.name})"


def make_graph(edges):
    """Build nodes from an adjacency mapping name -> list of successor names."""
    nodes = {name: Node(name) for name in edges}
    for name, succs in edges.items():
        for s in succs:
            if s not in nodes:
                nodes[s] = Node(s)
    for name, succs in edges.items():
        nodes[name].successors = [nodes[s] for s in succs]
    return nodes


def test_breadth_first_search_start_is_goal():
    """A node is reachable from itself (reflexivity of reachability)."""
    nodes = make_graph({"A": []})
    assert breadth_first_search(nodes["A"], nodes["A"]) is True


def test_breadth_first_search_direct_successor():
    """A direct successor is reachable."""
    nodes = make_graph({"A": ["B"], "B": []})
    assert breadth_first_search(nodes["A"], nodes["B"]) is True


def test_breadth_first_search_unreachable_returns_false():
    """An unreachable goal must return False, not hang or raise.

    The goal is in a disconnected component; a correct BFS exhausts the
    reachable set and returns False.
    """
    nodes = make_graph({"A": ["B"], "B": [], "C": ["D"], "D": []})
    assert breadth_first_search(nodes["A"], nodes["C"]) is False


def test_breadth_first_search_unreachable_isolated_goal():
    """A goal with no incoming edges from the start component is unreachable."""
    nodes = make_graph({"A": ["B"], "B": [], "Z": []})
    assert breadth_first_search(nodes["A"], nodes["Z"]) is False


def test_breadth_first_search_cycle_terminates():
    """BFS must terminate on a cyclic graph and find a reachable goal."""
    nodes = make_graph({"A": ["B"], "B": ["C"], "C": ["A"]})
    assert breadth_first_search(nodes["A"], nodes["C"]) is True


def test_breadth_first_search_cycle_unreachable_terminates():
    """BFS must terminate on a cyclic graph when goal is unreachable."""
    nodes = make_graph({"A": ["B"], "B": ["A"], "X": ["Y"], "Y": ["X"]})
    assert breadth_first_search(nodes["A"], nodes["X"]) is False


def test_breadth_first_search_self_loop_unreachable():
    """A self-loop must not cause infinite looping; unreachable goal -> False."""
    nodes = make_graph({"A": ["A"], "B": []})
    assert breadth_first_search(nodes["A"], nodes["B"]) is False


def test_breadth_first_search_long_chain():
    """Reachability holds along a long chain."""
    edges = {str(i): [str(i + 1)] for i in range(50)}
    edges["50"] = []
    nodes = make_graph(edges)
    assert breadth_first_search(nodes["0"], nodes["50"]) is True


def test_breadth_first_search_diamond_graph():
    """Reachability through a diamond-shaped DAG."""
    nodes = make_graph({"A": ["B", "C"], "B": ["D"], "C": ["D"], "D": []})
    assert breadth_first_search(nodes["A"], nodes["D"]) is True


def test_breadth_first_search_returns_bool():
    """Return value must be a bool for both reachable and unreachable cases."""
    nodes = make_graph({"A": ["B"], "B": [], "C": []})
    assert isinstance(breadth_first_search(nodes["A"], nodes["B"]), bool)
    assert isinstance(breadth_first_search(nodes["A"], nodes["C"]), bool)

